function validate([n, edges, score]) {
  if (!Number.isInteger(n) || n < 1 || n > 22) return 'n is an integer between 1 and 22.';
  if (!Array.isArray(score) || score.length !== n) return 'score needs exactly n values.';
  if (score.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each score is between 1 and 10^5.';
  if (!Array.isArray(edges) || edges.length > n * (n - 1) / 2) return 'edges has at most n * (n - 1) / 2 pairs.';
  const seen = new Set();
  const indegree = new Array(n).fill(0);
  const next = Array.from({ length: n }, () => []);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || u >= n || v < 0 || v >= n) return 'Nodes are labeled 0 to n - 1.';
    if (u === v) return 'An edge cannot join a node to itself.';
    if (seen.has(u * 32 + v)) return 'Each edge may appear only once.';
    seen.add(u * 32 + v);
    next[u].push(v);
    indegree[v]++;
  }
  // Kahn's algorithm removes every node exactly when the graph has no cycle.
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  for (let q = 0; q < queue.length; q++) {
    for (const v of next[queue[q]]) if (--indegree[v] === 0) queue.push(v);
  }
  if (queue.length !== n) return 'The graph must not contain a cycle.';
  return null;
}

