function maxProfit(n, edges, score) {
  const before = new Array(n).fill(0);
  for (const [from, to] of edges) {
    before[to] |= 1 << from;
  }

  const full = (1 << n) - 1;
  const dp = new Array(full + 1).fill(-1);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    if (dp[mask] < 0) continue;
    let position = 1;
    for (let rest = mask; rest > 0; rest &= rest - 1) {
      position++;
    }
    for (let node = 0; node < n; node++) {
      const placed = (mask >> node) & 1;
      if (!placed && (before[node] & mask) === before[node]) {
        const next = mask | (1 << node);
        dp[next] = Math.max(dp[next], dp[mask] + score[node] * position);
      }
    }
  }
  return dp[full];
}

