function maxProfit(n, edges, score) {
  // Build every topological order: fill the positions one by one with any node whose parents are all placed.
  const parents = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) parents[v].push(u);
  const placed = new Array(n).fill(false);
  let best = 0;
  const extend = (position, profit) => {
    if (position > n) {
      best = Math.max(best, profit);
      return;
    }
    for (let v = 0; v < n; v++) {
      if (placed[v] || parents[v].some(p => !placed[p])) continue;
      placed[v] = true;
      extend(position + 1, profit + score[v] * position);
      placed[v] = false;
    }
  };
  extend(1, 0);
  return best;
}

