function generate(rand, size) {
  // Up to 16 nodes keeps the 2^n table well inside the local time limit even with no edges at all.
  const n = size === 'large' ? 14 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  // Shuffle the labels; edges only go forward in this order, so the graph never has a cycle.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const density = rand() < 0.15 ? 0 : rand() * (size === 'large' ? 0.3 : 0.7);
  const edges = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (rand() < density) edges.push([order[i], order[j]]);
    }
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  const top = size === 'large' || rand() < 0.4 ? 100000 : 10;
  const score = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [n, edges, score];
}
